using System;
using System.Collections;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
namespace RollerSort.Editor {
 [InitializeOnLoad] public static class JourneyAnimationCheck {
  const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static RollerGame game;static int stage,oldLevel,oldCoins,oldVisited;static double started,ready;static int clicks;
  static JourneyAnimationCheck(){if(SessionState.GetBool("JourneyAnimationQA",false)){started=EditorApplication.timeSinceStartup;EditorApplication.update+=Tick;}}
  public static void Run(){SessionState.SetInt("AnimationOldLevel",PlayerPrefs.GetInt("level",1));SessionState.SetInt("AnimationOldCoins",PlayerPrefs.GetInt("coins",500));SessionState.SetInt("AnimationOldVisited",PlayerPrefs.GetInt("visitedJourney",0));SessionState.SetBool("JourneyAnimationQA",true);started=EditorApplication.timeSinceStartup;UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/RollerSort/Scenes/RollerSort.unity");EditorApplication.update+=Tick;EditorApplication.isPlaying=true;}
  static object Get(string n)=>typeof(RollerGame).GetField(n,F).GetValue(game);static void Set(string n,object v)=>typeof(RollerGame).GetField(n,F).SetValue(game,v);static object Call(string n,params object[] args)=>typeof(RollerGame).GetMethod(n,F).Invoke(game,args);static void Check(bool b,string m){if(!b)throw new Exception(m);}
  static void Tick(){try{if(EditorApplication.timeSinceStartup-started>30)throw new Exception("Animation QA timeout");if(!EditorApplication.isPlaying)return;EditorApplication.QueuePlayerLoopUpdate();Application.runInBackground=true;game=UnityEngine.Object.FindFirstObjectByType<RollerGame>();if(!game||Get("game")==null)return;
   if(stage==0){Set("diagnosticsActive",true);Set("level",10);Set("coins",750);Set("launchedFromJourney",true);Call("BuildLevel");game.enabled=false;Set("won",true);game.StartCoroutine((IEnumerator)Call("Victory"));ready=EditorApplication.timeSinceStartup;stage++;return;}
   if(stage==1&&EditorApplication.timeSinceStartup-ready>.9){Check((int)Get("coins")==810,"Reward not credited once");Check(((Text)Get("coinText")).text=="750","HUD credited before coin flight");var overlay=(RectTransform)Get("overlay");foreach(var button in overlay.GetComponentsInChildren<Button>()){var label=button.GetComponentInChildren<Text>();if(label&&label.text==GameLanguage.Text("Continue")){button.onClick.Invoke();button.onClick.Invoke();clicks++;break;}}Check(clicks==1,"Continue missing");ready=EditorApplication.timeSinceStartup;stage++;return;}
   if(stage==2&&EditorApplication.timeSinceStartup-ready>.45){Check(GameObject.Find("Reward flight")!=null,"Coin flight missing");Check((int)Get("level")==10&&!((bool)Get("journey")),"Coins must leave the completion card before Journey");stage++;return;}
   if(stage==3&&EditorApplication.timeSinceStartup-ready>2.0){Check((int)Get("level")==11,"Continue advanced more than once");Check((bool)Get("journey"),"Journey return missing");Check((bool)Get("journeyCompleted"),"Route transition not active");var route=GameObject.Find("Journey medals").GetComponent<RectTransform>();Check(route.anchoredPosition.y<0&&route.anchoredPosition.y>-160,"Route must scroll between nodes");stage++;return;}
   if(stage==4&&EditorApplication.timeSinceStartup-ready>3.1){Check(!(bool)Get("journeyCompleted"),"Route did not settle");Check(GameObject.Find("Level node 11")!=null&&GameObject.Find("Level node 10")==null,"Old level remains after scroll");Check(GameObject.Find("Current level halo")!=null,"Current level halo missing");Check((int)Get("coins")==810,"Duplicate Continue gave double reward");Set("level",10);Set("coins",750);Set("launchedFromJourney",false);Call("BuildLevel");Set("won",true);game.StartCoroutine((IEnumerator)Call("Victory"));ready=EditorApplication.timeSinceStartup;stage++;return;}
   if(stage==5&&EditorApplication.timeSinceStartup-ready>.8){var overlay=(RectTransform)Get("overlay");foreach(var button in overlay.GetComponentsInChildren<Button>()){var label=button.GetComponentInChildren<Text>();if(label&&label.text==GameLanguage.Text("Continue")){button.onClick.Invoke();break;}}ready=EditorApplication.timeSinceStartup;stage++;return;}
   if(stage==6&&EditorApplication.timeSinceStartup-ready>3){Check((int)Get("level")==11&&!(bool)Get("journey"),"Direct next-level flow failed");Check(GameObject.Find("Level transition")==null,"Transition overlay leaked");Check((int)Get("coins")==810,"Direct reward incorrect");Finish(true,null);}
  }catch(Exception e){Finish(false,e);}}
  static void Finish(bool ok,Exception e){foreach(string key in new[]{"level","coins","visitedJourney"})PlayerPrefs.SetInt(key,SessionState.GetInt(key=="level"?"AnimationOldLevel":key=="coins"?"AnimationOldCoins":"AnimationOldVisited",0));PlayerPrefs.Save();SessionState.SetBool("JourneyAnimationQA",false);EditorApplication.update-=Tick;if(ok)Debug.Log("ROLLER_JOURNEY_ANIMATION_OK: reward flight, delayed HUD, single Continue, animated 160pt map scroll, current halo and direct next-level reveal.");else Debug.LogException(e);EditorApplication.Exit(ok?0:1);}
 }
}
